import {
	type ApolloError,
	ApolloLink,
	HttpLink,
	split,
	ApolloClient,
	InMemoryCache
} from '@apollo/client'
import { BatchHttpLink } from '@apollo/client/link/batch-http'
import { onError } from '@apollo/client/link/error'
import { setContext } from '@apollo/client/link/context'
import { RetryLink } from '@apollo/client/link/retry'
import { GraphQLWsLink } from '@apollo/client/link/subscriptions'
import {
	getMainDefinition,
	relayStylePagination
} from '@apollo/client/utilities'
import { Kind, OperationTypeNode } from 'graphql'
import { createClient } from 'graphql-ws'
import { useAuthStore } from '@/stores/authStore'
import { API_URL, WS_URL } from '@/constants'
import { tokenRefreshLink } from './tokenRefreshLink'
import { router } from 'expo-router'
import { persistCache, AsyncStorageWrapper } from 'apollo3-cache-persist'
import { throttle } from 'lodash'
import { socketEmitter } from './socket'
import AsyncStorage from '@react-native-async-storage/async-storage'
import * as Sentry from '@sentry/react-native'

const isCloseEvent = (event: unknown): event is CloseEvent => {
	return typeof event === 'object' && event !== null && 'code' in event
}

const IGNORABLE_CLOSE_CODES = [
	1000, // Normal Closure
	1001, // Going Away
	4403 // Forbidden
]

const SAMPLED_CLOSE_CODES = [
	1006, // Abnormal Closure
	4408 // Connection initialization timeout
]

// Sample 1% of noisy close codes
const SAMPLE_RATE = 0.01

const reportWebSocketError = (errorOrCloseEvent: unknown) => {
	if (isCloseEvent(errorOrCloseEvent)) {
		if (IGNORABLE_CLOSE_CODES.includes(errorOrCloseEvent.code)) {
			return
		}
		if (
			SAMPLED_CLOSE_CODES.includes(errorOrCloseEvent.code) &&
			Math.random() > SAMPLE_RATE
		) {
			return
		}
		Sentry.captureException(
			new Error(
				`WebSocket closed with event code: ${errorOrCloseEvent.code}, reason: ${errorOrCloseEvent.reason}`
			),
			{
				extra: {
					code: errorOrCloseEvent.code,
					reason: errorOrCloseEvent.reason
				}
			}
		)
	} else if (errorOrCloseEvent instanceof Error) {
		Sentry.captureException(errorOrCloseEvent)
	} else {
		Sentry.captureException(new Error('WebSocket error occurred'), {
			extra: {
				event: errorOrCloseEvent
			}
		})
	}
}

export const retryLink = new RetryLink({
	delay: (count) => count * 500 * Math.random(),
	attempts: {
		max: 5,
		retryIf: (error: ApolloError | undefined) =>
			Boolean(
				error?.networkError ?? error?.message.includes('Network request failed')
			)
	}
})

export interface CreateApolloClientOptions {
	url?: string
	wsUrl?: string
}

export const onErrorLink = onError(({ graphQLErrors, networkError }) => {
	if (graphQLErrors) {
		const isUnauthenticated = graphQLErrors.some(
			({ extensions }) => extensions?.code === 'UNAUTHENTICATED'
		)
		if (isUnauthenticated) {
			useAuthStore.getState().setAuth(null)
			router.replace('/')
			return
		}
		if (graphQLErrors?.length) {
			graphQLErrors.forEach((error) => {
				// biome-ignore lint/suspicious/noConsole: necessary
				console.error(error)
			})
		}
		if (networkError) {
			// biome-ignore lint/suspicious/noConsole: necessary
			console.error(networkError)
		}
	}
})

export const apolloCache = new InMemoryCache({
	typePolicies: {
		Query: {
			fields: {
				organizations: relayStylePagination([
					'first',
					'after',
					'before',
					'last',
					'input'
				]),
				projectGroups: relayStylePagination(['input'])
			}
		},
		ProjectGroupRevision: {
			fields: {
				response: {
					merge(existing: string, incoming: string) {
						// never allow existing content to be overwritten by empty content
						// resolves empty chat streams
						if (existing && !incoming) {
							return existing
						}
						return incoming
					}
				}
			}
		}
	}
})

export async function createApolloClient() {
	const httpLink = split(
		({ query }) => {
			const definition = getMainDefinition(query)
			return (
				definition.kind === Kind.OPERATION_DEFINITION &&
				definition.operation === OperationTypeNode.QUERY
			)
		},
		new BatchHttpLink({
			uri: `${API_URL}/graphql`,
			credentials: 'include',
			batchMax: 100,
			batchInterval: 20,
			headers: undefined
		}),
		new HttpLink({
			uri: `${API_URL}/graphql`,
			credentials: 'include',
			headers: undefined
		})
	)

	let lostConnection = false
	const fireReconnectEvent = throttle(
		() => {
			socketEmitter.emit('reconnected')
		},
		10000,
		{ leading: true, trailing: true }
	)
	const wsLink = new GraphQLWsLink(
		createClient({
			url: `${WS_URL}/subscriptions`,
			keepAlive: 10000,
			retryAttempts: Infinity,
			shouldRetry: () => {
				return true
			},
			onNonLazyError: (errorOrCloseEvent) => {
				reportWebSocketError(errorOrCloseEvent)
			},
			on: {
				connected: () => {
					if (lostConnection) {
						lostConnection = false
						fireReconnectEvent()
					}
				},
				closed: (event) => {
					reportWebSocketError(event)
					if (!lostConnection) {
						lostConnection = true
					}
				},
				error: (error) => {
					reportWebSocketError(error)
				}
			},
			lazyCloseTimeout: 30000,
			connectionParams: async () => {
				const auth = useAuthStore.getState().auth
				if (auth?.accessToken) {
					return { authorization: auth.accessToken }
				}
				return {}
			}
		})
	)
	const wsSplitLink = wsLink
		? split(
				({ query }) => {
					const definition = getMainDefinition(query)
					return (
						definition.kind === Kind.OPERATION_DEFINITION &&
						definition.operation === OperationTypeNode.SUBSCRIPTION
					)
				},
				wsLink,
				httpLink
		  )
		: httpLink

	const links = [
		tokenRefreshLink,
		setContext((_, { headers }) => {
			const auth = useAuthStore.getState().auth
			return {
				headers: {
					...headers,
					...(auth?.accessToken ? { authorization: auth.accessToken } : {}),
					...(auth?.refreshToken
						? { 'x-anything-refresh-token': auth.refreshToken }
						: {})
				}
			}
		}),
		onErrorLink,
		retryLink,
		wsSplitLink
	]

	const link = ApolloLink.from(links)

	await persistCache({
		cache: apolloCache,
		storage: new AsyncStorageWrapper(AsyncStorage)
	})

	return new ApolloClient({
		link,
		cache: apolloCache,
		defaultOptions: {
			watchQuery: {
				fetchPolicy: 'cache-and-network',
				returnPartialData: true
			}
		}
	})
}
